package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lianxibu.site.repository.jobs.*;import com.lianxibu.site.service.jobs.OperationalRuleEngine.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.Test;
class BacklogMonitoringCycleTest extends BacklogHistoryObservationServiceTest {
 static final Key KEY=new Key("OPS-01","java","fictional-backlog");
 OperationalJdbcStore store(Fixture f){return new OperationalJdbcStore(new JdbcOperationalSummaries(f.source),new JdbcJobRecords(f.source),f.clock);}
 BacklogMonitoringCycle cycle(Fixture f,BacklogHistoryObservationService facts,OperationalMonitoringService.Store store){var cycle=new BacklogMonitoringCycle(KEY,facts,store,()->new OperationalMonitoringService.Configuration(1,MonitoringFixtures.complete()),f.writes,f.clock);cycle.start();return cycle;}
 @Test void nativeHistoryAlarmAndReceiptCommitTogetherAndRestartSkipsTheSameMinute(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){
  var history=new JdbcBacklogHistory(f.source,scope);var root=root(f,history);var source=spy(source(f,history,mock(DispatchReadinessService.class),settings(false)));var store=store(f);f.clock.now=f.clock.now.plusSeconds(7*86400L);var cycle=cycle(f,source,store);
  assertEquals(BacklogMonitoringCycle.Outcome.SAMPLED,cycle.tick());assertEquals(Level.CRITICAL,store.read(KEY).level());assertEquals(Status.TELEMETRY_UNKNOWN,store.read(KEY).status());assertEquals(1,rr(f,()->history.read(root)).revision());assertEquals(1,f.sql.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='ops_rule'",Integer.class));
  assertEquals(BacklogMonitoringCycle.Outcome.ALREADY_SAMPLED,cycle(f,source,store).tick());verify(source,times(1)).acquire();assertEquals(1,rr(f,()->history.read(root)).revision());assertEquals(1,rr(f,history::mutation).sequence());
  f.clock.now=f.clock.now.plusSeconds(60);cycle.tick();assertEquals(2,rr(f,()->history.read(root)).revision());assertEquals(1,rr(f,history::mutation).sequence());assertEquals(Level.CRITICAL,store.read(KEY).level());
 }}
 @Test void historyCasFailureRollsBackStateNoticeAndHistoryThenTheSameMinuteCanRetry(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){
  var history=new JdbcBacklogHistory(f.source,scope);var root=root(f,history);var source=source(f,history,mock(DispatchReadinessService.class),settings(false));var original=store(f);f.clock.now=f.clock.now.plusSeconds(7*86400L);cycle(f,source,original).tick();var before=original.read(KEY);var fail=new AtomicBoolean(true);
  var broken=new OperationalMonitoringService.Store(){public State committed(String k,String h){return original.committed(k,h);}public State read(Key k){return original.read(k);}public void save(State p,State n,List<Notice> notices,String k,String h,String owner,String reason){original.save(p,n,notices,k,h,owner,reason);if(fail.get())f.sql.update("UPDATE runtime_settings SET revision=revision+1 WHERE setting_key=?",JdbcBacklogHistory.key(root.id()));}};
  f.clock.now=f.clock.now.plusSeconds(60);var cycle=cycle(f,source,broken);assertThrows(RuntimeException.class,cycle::tick);assertEquals(before,original.read(KEY));assertEquals(1,rr(f,()->history.read(root)).revision());assertEquals(1,f.sql.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='ops_rule'",Integer.class));
  fail.set(false);assertEquals(BacklogMonitoringCycle.Outcome.SAMPLED,cycle.tick());assertEquals(before.revision()+1,original.read(KEY).revision());assertEquals(2,rr(f,()->history.read(root)).revision());
 }}
 @Test void defaultStoppedUnknownSnapshotAndOwnedOuterTransactionPreserveOldAlarm(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){
  var history=new JdbcBacklogHistory(f.source,scope);root(f,history);var source=source(f,history,mock(DispatchReadinessService.class),settings(false));var store=store(f);var cold=new BacklogMonitoringCycle(KEY,source,store,()->new OperationalMonitoringService.Configuration(1,MonitoringFixtures.complete()),f.writes,f.clock);assertEquals(BacklogMonitoringCycle.Outcome.STOPPED,cold.tick());assertNull(store.read(KEY));f.clock.now=f.clock.now.plusSeconds(7*86400L);var cycle=cycle(f,source,store);cycle.tick();f.clock.now=f.clock.now.plusSeconds(60);
  var missing=mock(BacklogHistoryObservationService.class);cycle(f,missing,store).tick();assertEquals(Status.TELEMETRY_UNKNOWN,store.read(KEY).status());assertEquals(Level.CRITICAL,store.read(KEY).level());assertEquals(29,store.read(KEY).counters().size());assertThrows(IllegalStateException.class,()->new org.springframework.transaction.support.TransactionTemplate(f.tx).execute(s->cycle.tick()));
 }}
 @Test void crossMinuteUnknownAndClockRollbackRejectWithoutSavingStaleHistory(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){
  var history=new JdbcBacklogHistory(f.source,scope);var root=root(f,history);var source=source(f,history,mock(DispatchReadinessService.class),settings(false));var acquired=source.acquire();var delayed=mock(BacklogHistoryObservationService.class);when(delayed.acquire()).thenAnswer(call->{f.clock.now=f.clock.now.plusSeconds(61);return acquired;});var store=store(f);cycle(f,delayed,store).tick();assertEquals(Status.TELEMETRY_UNKNOWN,store.read(KEY).status());verify(delayed,never()).save(any());assertNull(rr(f,()->history.read(root)));f.clock.now=f.clock.now.minusSeconds(120);assertThrows(IllegalStateException.class,()->cycle(f,source,store).tick());
 }}
 @Test void singleFlightAndStopAfterReadCannotWriteALateHistoryOrAlarm()throws Exception{var f=fixture();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var source=mock(BacklogHistoryObservationService.class);when(source.acquire()).thenAnswer(call->{entered.countDown();assertTrue(release.await(2,TimeUnit.SECONDS));return null;});var store=store(f);var cycle=cycle(f,source,store);var pool=Executors.newSingleThreadExecutor();try{var future=pool.submit(cycle::tick);assertTrue(entered.await(1,TimeUnit.SECONDS));assertEquals(BacklogMonitoringCycle.Outcome.BUSY,cycle.tick());cycle.stop();release.countDown();assertEquals(BacklogMonitoringCycle.Outcome.STOPPED,future.get(2,TimeUnit.SECONDS));assertNull(store.read(KEY));verify(source,never()).save(any());}finally{release.countDown();pool.shutdownNow();}}
}
